mapper.select:
SELECT t.replyId, t.commentId, t.userId, t.content, t.anonymity, t.likedTimes, t.createTime, t.hidden FROM ( SELECT r.id AS replyId, r.comment_id AS commentId, r.user_id AS userId, r.content, r.anonymity, COALESCE(r.liked_times, 0) AS likedTimes, r.create_time AS createTime, r.hidden, ROW_NUMBER() OVER ( PARTITION BY r.comment_id ORDER BY COALESCE(r.liked_times, 0) DESC, r.create_time DESC, r.id DESC ) AS rn FROM comment_reply r WHERE r.comment_id IN
#{commentId}
AND (r.hidden = 0 OR r.hidden IS NULL) ) t WHERE t.rn <= #{limitPerComment} ORDER BY t.commentId, t.likedTimes DESC, t.createTime DESC, t.replyId DESC
